objective.code:
model.setObjective(
    quicksum((Price * Distance[i][j] / 2.0) * number[i, j]
             for i in range(I)
             for j in range(J)),
    GRB.MINIMIZE
)

constraints.code:
for i in range(I):
    model.addConstr(
        sum(number[i, j] for j in range(J)) <= NumDepot[i]
    )

for j in range(J):
    model.addConstr(
        sum(number[i, j] for i in range(I)) == NumPort[j]
    )

for i in range(I):
    for j in range(J):
        model.addConstr(number[i, j] >= 0)
